#!/usr/bin/env python3
from pathlib import Path
import shutil
import py_compile

ROOT = Path.cwd()
AUTO = ROOT / "automation"
BACKUP = AUTO / "backups" / "pre_v002"
FILES = {'__init__.py': '__version__ = "0.0.2"\n', 'contracts.py': 'from __future__ import annotations\nfrom dataclasses import dataclass\n\n@dataclass(frozen=True)\nclass StageContract:\n    stage_id: str\n    title: str\n    script: str | None = None\n    requires: tuple[str, ...] = ()\n    produces: tuple[str, ...] = ()\n    dependencies: tuple[str, ...] = ()\n    network_access: bool = False\n    science_pixels_read: bool = False\n    non_science_pixels_read: bool = False\n    transient_detector_rerun: bool = False\n    candidate_state_mutation: bool = False\n    retryable: bool = False\n    notes: str = ""\n\n    @property\n    def safe_default(self) -> bool:\n        return (\n            not self.network_access\n            and not self.transient_detector_rerun\n            and not self.candidate_state_mutation\n        )\n\n    @property\n    def declared_guards(self) -> dict[str, bool]:\n        return {\n            "network_access": self.network_access,\n            "science_pixels_read": self.science_pixels_read,\n            "non_science_pixels_read": self.non_science_pixels_read,\n            "transient_detector_rerun": self.transient_detector_rerun,\n            "candidate_state_mutation": self.candidate_state_mutation,\n        }\n', 'state_store.py': 'from __future__ import annotations\nimport json\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Any\n\ndef utc_now() -> str:\n    return datetime.now(timezone.utc).isoformat()\n\nclass StateStore:\n    def __init__(self, root: Path):\n        self.root = root\n        self.root.mkdir(parents=True, exist_ok=True)\n        self.events_path = self.root / "events.jsonl"\n        self.snapshot_path = self.root / "snapshot.json"\n\n    def append(self, event_type: str, payload: dict[str, Any]) -> dict[str, Any]:\n        event = {\n            "timestamp_utc": utc_now(),\n            "event_type": event_type,\n            "payload": payload,\n        }\n        with self.events_path.open("a", encoding="utf-8") as fh:\n            fh.write(json.dumps(event, sort_keys=True, default=str) + "\\n")\n        return event\n\n    def events(self) -> list[dict[str, Any]]:\n        if not self.events_path.is_file():\n            return []\n        out = []\n        for line in self.events_path.read_text(encoding="utf-8").splitlines():\n            if not line.strip():\n                continue\n            try:\n                out.append(json.loads(line))\n            except Exception:\n                out.append({\n                    "timestamp_utc": None,\n                    "event_type": "malformed_event",\n                    "payload": {"raw": line},\n                })\n        return out\n\n    def write_snapshot(self, obj: dict[str, Any]) -> None:\n        tmp = self.snapshot_path.with_suffix(".json.tmp")\n        tmp.write_text(\n            json.dumps(obj, indent=2, sort_keys=True, default=str) + "\\n",\n            encoding="utf-8",\n        )\n        tmp.replace(self.snapshot_path)\n', 'verifier.py': 'from __future__ import annotations\nimport json\nfrom pathlib import Path\nfrom typing import Any\nfrom .contracts import StageContract\n\nGUARD_ALIASES = {\n    "network_access": ("network_access",),\n    "science_pixels_read": ("science_pixels_read",),\n    "non_science_pixels_read": ("non_science_pixels_read", "control_pixels_read"),\n    "transient_detector_rerun": ("transient_detector_rerun",),\n    "candidate_state_mutation": ("candidate_state_mutation",),\n}\n\ndef _find_guard_value(guards: dict[str, Any], name: str):\n    for alias in GUARD_ALIASES.get(name, (name,)):\n        if alias in guards:\n            return True, guards[alias]\n    return False, None\n\ndef verify_stage_output(root: Path, stage: StageContract) -> dict[str, Any]:\n    checks, failures, warnings = [], [], []\n\n    for rel in stage.produces:\n        p = root / rel\n        ok = p.exists()\n        checks.append({\n            "kind": "output_exists",\n            "target": rel,\n            "status": "PASS" if ok else "FAIL",\n        })\n        if not ok:\n            failures.append(f"missing declared output: {rel}")\n\n    primary = next(\n        (root / p for p in stage.produces\n         if p.lower().endswith(".json") and (root / p).is_file()),\n        None,\n    )\n\n    output_guards = None\n    guard_source = None\n\n    if primary is not None:\n        try:\n            obj = json.loads(primary.read_text(encoding="utf-8"))\n            if isinstance(obj, dict) and isinstance(obj.get("guards"), dict):\n                output_guards = obj["guards"]\n                guard_source = str(primary.relative_to(root))\n        except Exception as exc:\n            failures.append(\n                f"cannot parse JSON output {primary}: "\n                f"{type(exc).__name__}: {exc}"\n            )\n\n    if output_guards is None:\n        status = "WARN" if stage.script is not None else "SKIP"\n        checks.append({\n            "kind": "guard_block",\n            "target": None if primary is None else str(primary.relative_to(root)),\n            "status": status,\n        })\n        if stage.script is not None:\n            warnings.append("no machine-readable guards block found in primary JSON output")\n    else:\n        for name, expected in stage.declared_guards.items():\n            present, actual = _find_guard_value(output_guards, name)\n\n            if not present:\n                if expected:\n                    status = "FAIL"\n                    failures.append(\n                        f"declared TRUE guard {name!r} absent from output"\n                    )\n                else:\n                    status = "WARN"\n                    warnings.append(\n                        f"declared FALSE guard {name!r} absent from legacy output"\n                    )\n                checks.append({\n                    "kind": "guard",\n                    "guard": name,\n                    "expected": expected,\n                    "actual": None,\n                    "status": status,\n                })\n                continue\n\n            ok = bool(actual) is bool(expected)\n            checks.append({\n                "kind": "guard",\n                "guard": name,\n                "expected": expected,\n                "actual": actual,\n                "status": "PASS" if ok else "FAIL",\n            })\n            if not ok:\n                failures.append(\n                    f"guard mismatch {name}: "\n                    f"actual={actual!r} expected={expected!r}"\n                )\n\n    return {\n        "stage_id": stage.stage_id,\n        "passed": not failures,\n        "failures": failures,\n        "warnings": warnings,\n        "checks": checks,\n        "guard_source": guard_source,\n    }\n', 'runner.py': 'from __future__ import annotations\nimport argparse\nimport json\nimport subprocess\nimport sys\nfrom pathlib import Path\nfrom typing import Any\n\nfrom .registry_order01 import ORDER01_STAGES, by_id\nfrom .state_store import StateStore\nfrom .verifier import verify_stage_output\n\nROOT = Path(__file__).resolve().parents[1]\nAUTO = ROOT / "automation"\nSTATE = StateStore(AUTO / "state")\nBASELINE = AUTO / "baseline_order01_v001.json"\n\ndef get_path(obj: Any, dotted: str):\n    cur = obj\n    for part in dotted.split("."):\n        if isinstance(cur, dict) and part in cur:\n            cur = cur[part]\n        else:\n            raise KeyError(dotted)\n    return cur\n\ndef verify_baseline():\n    manifest = json.loads(BASELINE.read_text(encoding="utf-8"))\n    results = []\n\n    for check in manifest["checks"]:\n        path = ROOT / check["file"]\n        result = {\n            "id": check["id"],\n            "file": check["file"],\n            "passed": False,\n            "detail": "",\n        }\n\n        if not path.is_file():\n            result["detail"] = "missing file"\n            results.append(result)\n            continue\n\n        try:\n            obj = json.loads(path.read_text(encoding="utf-8"))\n\n            if check["type"] == "equals":\n                actual = get_path(obj, check["path"])\n                result["passed"] = actual == check["expected"]\n                result["detail"] = (\n                    f"actual={actual!r} expected={check[\'expected\']!r}"\n                )\n\n            elif check["type"] == "all_field_equals":\n                rows = get_path(obj, check["list_path"])\n                vals = [\n                    r.get(check["field"])\n                    for r in rows if isinstance(r, dict)\n                ]\n                result["passed"] = (\n                    len(vals) == int(check["expected_count"])\n                    and all(v == check["expected"] for v in vals)\n                )\n                result["detail"] = f"count={len(vals)} values={vals}"\n\n            else:\n                result["detail"] = (\n                    f"unsupported check type: {check[\'type\']}"\n                )\n\n        except Exception as exc:\n            result["detail"] = f"{type(exc).__name__}: {exc}"\n\n        results.append(result)\n\n    return all(r["passed"] for r in results), results\n\ndef stage_status(stage):\n    req = [(p, (ROOT / p).exists()) for p in stage.requires]\n    prod = [(p, (ROOT / p).exists()) for p in stage.produces]\n    script_exists = (\n        None if stage.script is None else (ROOT / stage.script).is_file()\n    )\n\n    stages = by_id()\n    deps = []\n    for dep_id in stage.dependencies:\n        ds = stages.get(dep_id)\n        dep_ok = False if ds is None else (\n            bool(ds.produces)\n            and all((ROOT / p).exists() for p in ds.produces)\n        )\n        deps.append((dep_id, dep_ok))\n\n    return {\n        "ready": (\n            all(ok for _, ok in req)\n            and all(ok for _, ok in deps)\n            and script_exists is not False\n        ),\n        "complete": bool(prod) and all(ok for _, ok in prod),\n        "script_exists": script_exists,\n        "requirements": req,\n        "dependencies": deps,\n        "products": prod,\n        "guards": stage.declared_guards,\n    }\n\ndef print_verification(v):\n    print(f"Stage verification: {v[\'stage_id\']}")\n\n    for c in v["checks"]:\n        status = c.get("status", "?")\n\n        if c["kind"] == "guard":\n            print(\n                f"  [{status}] guard {c[\'guard\']}: "\n                f"actual={c.get(\'actual\')!r} "\n                f"expected={c.get(\'expected\')!r}"\n            )\n        elif c["kind"] == "output_exists":\n            print(f"  [{status}] output {c[\'target\']}")\n        else:\n            print(\n                f"  [{status}] {c[\'kind\']} "\n                f"{c.get(\'target\') or \'\'}".rstrip()\n            )\n\n    for warning in v["warnings"]:\n        print(f"  WARNING: {warning}")\n    for failure in v["failures"]:\n        print(f"  FAILURE: {failure}")\n\n    print("  RESULT:", "PASS" if v["passed"] else "FAIL")\n\ndef cmd_status(_args):\n    print("Transient automation v0.0.2 - Order01 registry status\\n")\n\n    for stage in ORDER01_STAGES:\n        s = stage_status(stage)\n        state = (\n            "COMPLETE" if s["complete"]\n            else "READY" if s["ready"]\n            else "BLOCKED"\n        )\n        print(f"{stage.stage_id:38} {state}")\n\n        if stage.script and s["script_exists"] is False:\n            print(f"  missing script: {stage.script}")\n\n        for dep, ok in s["dependencies"]:\n            if not ok:\n                print(f"  incomplete dependency: {dep}")\n\n        for p, ok in s["requirements"]:\n            if not ok:\n                print(f"  missing requirement: {p}")\n\n        for p, ok in s["products"]:\n            if not ok:\n                print(f"  missing product: {p}")\n\ndef cmd_verify_baseline(_args):\n    ok, results = verify_baseline()\n    print("ORDER01 FROZEN BASELINE VERIFICATION\\n")\n\n    for r in results:\n        print(f"[{\'PASS\' if r[\'passed\'] else \'FAIL\'}] {r[\'id\']}")\n        print(f"       {r[\'detail\']}")\n\n    print("\\nBASELINE STATUS:", "PASS" if ok else "FAIL")\n\n    STATE.append(\n        "baseline_verification",\n        {"passed": ok, "checks": results},\n    )\n    STATE.write_snapshot({\n        "baseline_passed": ok,\n        "checks": results,\n        "framework_version": "0.0.2",\n    })\n    return 0 if ok else 2\n\ndef cmd_verify_stage(args):\n    stage = by_id().get(args.stage)\n    if stage is None:\n        print(f"Unknown stage: {args.stage}", file=sys.stderr)\n        return 2\n\n    v = verify_stage_output(ROOT, stage)\n    print_verification(v)\n    STATE.append("stage_verification", v)\n    return 0 if v["passed"] else 4\n\ndef cmd_verify_all(_args):\n    print("REGISTERED STAGE OUTPUT/GUARD VERIFICATION\\n")\n    all_ok = True\n\n    for stage in ORDER01_STAGES:\n        v = verify_stage_output(ROOT, stage)\n        print_verification(v)\n        print()\n        STATE.append("stage_verification", v)\n        if not v["passed"]:\n            all_ok = False\n\n    print("VERIFY-ALL STATUS:", "PASS" if all_ok else "FAIL")\n    return 0 if all_ok else 4\n\ndef cmd_plan(_args):\n    print("SAFE AUTOMATION PLAN\\n")\n\n    for stage in ORDER01_STAGES:\n        s = stage_status(stage)\n\n        if s["complete"]:\n            action = "VERIFY_EXISTING_OUTPUT"\n        elif s["ready"]:\n            action = "ELIGIBLE_FOR_EXECUTION"\n        else:\n            action = "BLOCKED"\n\n        print(f"{stage.stage_id:38} {action}")\n\n    print("\\nNo stage was executed.")\n\ndef failure_classification(stage, returncode, verification=None):\n    if returncode != 0:\n        return (\n            "RETRYABLE_PROCESS_FAILURE"\n            if stage.retryable\n            else "TERMINAL_PROCESS_FAILURE"\n        )\n\n    if verification is not None and not verification["passed"]:\n        return "OUTPUT_GUARD_OR_PROVENANCE_FAILURE"\n\n    return None\n\ndef execute_stage(stage, args):\n    s = stage_status(stage)\n\n    if stage.script is None:\n        print("Frozen artifact only; no executable script registered.")\n        return 2\n\n    if not s["ready"]:\n        print("Stage is not ready; run `status`.")\n        STATE.append("stage_failure", {\n            "stage_id": stage.stage_id,\n            "classification": "BLOCKED_PREREQUISITE",\n        })\n        return 2\n\n    if s["complete"] and not args.force:\n        print("Stage already complete. No execution performed.")\n        v = verify_stage_output(ROOT, stage)\n        print_verification(v)\n        return 0 if v["passed"] else 4\n\n    if stage.network_access and not args.allow_network:\n        print("REFUSED: --allow-network required.")\n        return 3\n\n    if stage.candidate_state_mutation and not args.allow_state_mutation:\n        print("REFUSED: --allow-state-mutation required.")\n        return 3\n\n    if stage.transient_detector_rerun and not args.allow_detector_rerun:\n        print("REFUSED: --allow-detector-rerun required.")\n        return 3\n\n    extra_retries = max(0, int(getattr(args, "retries", 0) or 0))\n    attempts = 1 + (extra_retries if stage.retryable else 0)\n    cmd = [sys.executable, str(ROOT / stage.script)]\n\n    for attempt in range(1, attempts + 1):\n        print(\n            f"EXECUTING attempt {attempt}/{attempts}: "\n            + " ".join(cmd)\n        )\n        print(\n            "Declared guards:",\n            json.dumps(s["guards"], sort_keys=True),\n        )\n\n        STATE.append("stage_start", {\n            "stage_id": stage.stage_id,\n            "attempt": attempt,\n            "attempts": attempts,\n            "command": cmd,\n            "declared_guards": s["guards"],\n        })\n\n        proc = subprocess.run(cmd, cwd=ROOT)\n\n        if proc.returncode == 0:\n            v = verify_stage_output(ROOT, stage)\n            print()\n            print_verification(v)\n\n            classification = failure_classification(\n                stage, proc.returncode, v\n            )\n\n            if classification is None:\n                STATE.append("stage_success", {\n                    "stage_id": stage.stage_id,\n                    "attempt": attempt,\n                    "verification": v,\n                })\n                STATE.write_snapshot({\n                    "last_successful_stage": stage.stage_id,\n                    "framework_version": "0.0.2",\n                })\n                return 0\n\n            print("FAILURE CLASSIFICATION:", classification)\n            STATE.append("stage_failure", {\n                "stage_id": stage.stage_id,\n                "attempt": attempt,\n                "returncode": proc.returncode,\n                "classification": classification,\n                "verification": v,\n            })\n            return 4\n\n        classification = failure_classification(\n            stage, proc.returncode\n        )\n        print("FAILURE CLASSIFICATION:", classification)\n\n        STATE.append("stage_failure", {\n            "stage_id": stage.stage_id,\n            "attempt": attempt,\n            "returncode": proc.returncode,\n            "classification": classification,\n        })\n\n        if (\n            classification != "RETRYABLE_PROCESS_FAILURE"\n            or attempt >= attempts\n        ):\n            return proc.returncode or 5\n\n        print(\n            "Retryable failure; retrying because this stage "\n            "contract explicitly allows it."\n        )\n\n    return 5\n\ndef _next_stage():\n    for stage in ORDER01_STAGES:\n        s = stage_status(stage)\n        if not s["complete"] and s["ready"]:\n            return stage\n    return None\n\ndef cmd_run(args):\n    stage = by_id().get(args.stage)\n    if stage is None:\n        print(f"Unknown stage: {args.stage}", file=sys.stderr)\n        return 2\n    return execute_stage(stage, args)\n\ndef cmd_run_next(args):\n    stage = _next_stage()\n\n    if stage is None:\n        incomplete = [\n            s for s in ORDER01_STAGES\n            if not stage_status(s)["complete"]\n        ]\n\n        if incomplete:\n            print("No executable stage is currently READY.")\n            print("Blocked incomplete stages:")\n            for st in incomplete:\n                print(f"  {st.stage_id}")\n            return 2\n\n        print("All currently registered stages are complete.")\n        print("RUN-NEXT STATUS: NOTHING_TO_DO")\n        return 0\n\n    print(f"Dependency traversal selected: {stage.stage_id}")\n    return execute_stage(stage, args)\n\ndef cmd_resume(args):\n    for event in reversed(STATE.events()):\n        if event.get("event_type") != "stage_failure":\n            continue\n\n        sid = event.get("payload", {}).get("stage_id")\n        stage = by_id().get(sid)\n\n        if stage is None:\n            continue\n\n        if stage_status(stage)["complete"] and not args.force:\n            continue\n\n        print(\n            "Resume selected most recent incomplete failed stage: "\n            f"{stage.stage_id}"\n        )\n        return execute_stage(stage, args)\n\n    print(\n        "No incomplete failed stage found; falling back to "\n        "dependency-aware run-next."\n    )\n    return cmd_run_next(args)\n\ndef add_execution_flags(parser):\n    parser.add_argument("--force", action="store_true")\n    parser.add_argument("--allow-network", action="store_true")\n    parser.add_argument("--allow-state-mutation", action="store_true")\n    parser.add_argument("--allow-detector-rerun", action="store_true")\n    parser.add_argument(\n        "--retries",\n        type=int,\n        default=0,\n        help=(\n            "Extra retries; honored only for stages explicitly "\n            "marked retryable."\n        ),\n    )\n\ndef build_parser():\n    p = argparse.ArgumentParser(\n        description="Transient automation runner v0.0.2"\n    )\n    sub = p.add_subparsers(dest="cmd", required=True)\n\n    s = sub.add_parser("status")\n    s.set_defaults(func=cmd_status)\n\n    s = sub.add_parser("verify-baseline")\n    s.set_defaults(func=cmd_verify_baseline)\n\n    s = sub.add_parser("verify-stage")\n    s.add_argument("--stage", required=True)\n    s.set_defaults(func=cmd_verify_stage)\n\n    s = sub.add_parser("verify-all")\n    s.set_defaults(func=cmd_verify_all)\n\n    s = sub.add_parser("plan")\n    s.set_defaults(func=cmd_plan)\n\n    s = sub.add_parser("run")\n    s.add_argument("--stage", required=True)\n    add_execution_flags(s)\n    s.set_defaults(func=cmd_run)\n\n    s = sub.add_parser("run-next")\n    add_execution_flags(s)\n    s.set_defaults(func=cmd_run_next)\n\n    s = sub.add_parser("resume")\n    add_execution_flags(s)\n    s.set_defaults(func=cmd_resume)\n\n    return p\n\ndef main():\n    args = build_parser().parse_args()\n    return int(args.func(args) or 0)\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n', 'README_AUTOMATION_V002.md': '# Transient automation framework v0.0.2\n\nv0.0.2 adds execution control without changing scientific results.\n\nNew commands:\n\n```powershell\n& ".\\.venv\\Scripts\\python.exe" -m automation.runner verify-baseline\n& ".\\.venv\\Scripts\\python.exe" -m automation.runner verify-all\n& ".\\.venv\\Scripts\\python.exe" -m automation.runner verify-stage --stage dasch_stellar_shape_v028as\n& ".\\.venv\\Scripts\\python.exe" -m automation.runner status\n& ".\\.venv\\Scripts\\python.exe" -m automation.runner run-next\n& ".\\.venv\\Scripts\\python.exe" -m automation.runner resume\n```\n\n`run-next` selects the first incomplete stage whose declared dependencies and\nrequirements are satisfied.\n\n`resume` first looks for the most recent failed incomplete stage. If none exists,\nit falls back to `run-next`.\n\nNetwork access, candidate-state mutation, and frozen-detector reruns remain\nexplicit opt-in safety gates.\n\nFor the current Order01 registry, `run-next` should return:\n\n```text\nAll currently registered stages are complete.\nRUN-NEXT STATUS: NOTHING_TO_DO\n```\n'}

def main():
    print("="*112)
    print("TRANSIENT AUTOMATION FRAMEWORK UPGRADE v0.0.2")
    print("="*112)
    print("NO NETWORK ACCESS.")
    print("SCIENCE PIXELS ARE NOT READ.")
    print("Frozen transient detector is NOT rerun.")
    print("No science/result artifact is modified.")
    print("No candidate state is changed.\n")

    if not AUTO.is_dir():
        print(f"FAIL: automation directory not found: {AUTO}")
        return 2

    required = [
        AUTO/"runner.py",
        AUTO/"contracts.py",
        AUTO/"state_store.py",
        AUTO/"registry_order01.py",
        AUTO/"baseline_order01_v001.json",
    ]
    missing = [p for p in required if not p.is_file()]
    if missing:
        print("FAIL: automation v0.0.1 foundation is incomplete:")
        for p in missing:
            print("  " + str(p))
        return 2

    BACKUP.mkdir(parents=True, exist_ok=True)
    for name in ("__init__.py","contracts.py","state_store.py","runner.py"):
        src = AUTO/name
        dst = BACKUP/name
        if src.is_file() and not dst.exists():
            shutil.copy2(src, dst)

    for rel, content in FILES.items():
        p = AUTO/rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(content, encoding="utf-8")
        print(f"Updated: {p.relative_to(ROOT)}")

    failures = []
    py_files = sorted(
        p for p in AUTO.rglob("*.py")
        if "backups" not in p.parts
    )

    print(f"\nCompiling automation package ({len(py_files)} Python files):")
    for p in py_files:
        try:
            py_compile.compile(str(p), doraise=True)
            print(f"  PASS {p.relative_to(ROOT)}")
        except Exception as exc:
            failures.append((p, exc))
            print(f"  FAIL {p.relative_to(ROOT)}: {exc}")

    if failures:
        print("\nAUTOMATION FRAMEWORK UPGRADE STATUS: FAIL")
        print(f"Backup: {BACKUP.relative_to(ROOT)}")
        return 3

    print("\nAUTOMATION FRAMEWORK UPGRADE STATUS: PASS")
    print(f"Pre-v0.0.2 framework backup: {BACKUP.relative_to(ROOT)}")
    print("\nNext commands:")
    print(r'  & ".\.venv\Scripts\python.exe" -m automation.runner verify-baseline')
    print(r'  & ".\.venv\Scripts\python.exe" -m automation.runner verify-all')
    print(r'  & ".\.venv\Scripts\python.exe" -m automation.runner status')
    print(r'  & ".\.venv\Scripts\python.exe" -m automation.runner run-next')
    print("\nNo science was executed.")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
